var contactFilter = 'all';
var contactSettings = {};
function setContactFilter(f) {
    contactFilter = f;
    document.querySelectorAll('#page-inbox .chip[data-cf]').forEach(function (c) { c.classList.toggle('active', c.dataset.cf === f); });
    loadContactMessages();
}
