        const inlineBackLabel = (cmdRecord.inline_back_label && String(cmdRecord.inline_back_label).trim()) || strings.back;
        const hasInlineBack = inlineRows.some(row => row.some(b => b.type === 'command' && b.value === cmdRecord.parent));
